fn dget(dentry: *mut dentry) -> *mut dentry {
if !dentry.is_null() {
unsafe { lockref_get(core::ptr::addr_of_mut!((*dentry).d_lockref)) };
}
dentry
}

fn d_unhashed(dentry: *const dentry) -> i32 {
hlist_bl_unhashed(unsafe { core::ptr::addr_of!((*dentry).d_hash) }) as i32
}

fn d_unlinked(dentry: *const dentry) -> i32 {
(d_unhashed(dentry) != 0 && !IS_ROOT__2!(dentry)) as i32
}

